(r, big) => {
    const n = big ? 1000 : r.int(1, 5);
    const sentence = () => {
      const words = [];
      let len = -1;
      const cap = big ? 1000 : 20;
      while (true) {
        const w = r.str(r.int(1, 4), "abc");
        if (len + 1 + w.length > cap) break;
        words.push(w); len += 1 + w.length;
        if (!big && r.bool(0.3)) break;
        if (big && r.bool(0.01)) break;
      }
      return words.join(" ");
    };
    return [Array.from({ length: n }, sentence)];
  }

