function mostWords(sentences: string[]): number {
  let best = 0;
  for (const s of sentences) {
    let words = 1;
    for (let i = 0; i < s.length; i++) if (s[i] === " ") words++;
    best = Math.max(best, words);
  }
  return best;
}

